import React, { useState } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import { useCourseContext } from '../../context/CourContext';
import './admindashboard.css';
import { Link } from 'react-router-dom';
import { useQuizContext } from '../../context/QuizContext';


const CourseDescription = ({ description }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  
  if (!description) {
    return <span style={{color: '#999', fontStyle: 'italic'}}>Aucune description</span>;
  }

  const displayText = isExpanded ? description : `${description.substring(0, 36)}...`;

  return (
    <div className="course-description-container">
      <p className={`course-description-text ${!isExpanded ? 'course-description-truncated' : ''}`}>
        {displayText}
      </p>
      {description.length > 36 && (
        <button 
          className="see-more-btn"
          onClick={() => setIsExpanded(!isExpanded)}
        >
          {isExpanded ? 'Voir moins' : 'Voir plus'}
        </button>
      )}
    </div>
  );
};

const AdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const { courses, addCourse, deleteCourse } = useCourseContext();
    const { quizze, addQuiz, updateQuiz, deleteQuiz } = useQuizContext(); 

  const [activeTab, setActiveTab] = useState('overview');
  const [showNewCourseForm, setShowNewCourseForm] = useState(false);
  const [showNewQuizForm, setShowNewQuizForm] = useState(false);
  const [editingQuiz, setEditingQuiz] = useState(null);

  // État pour le nouveau cours
  const [newCourse, setNewCourse] = useState({
    title: '',
    category: '',
    instructor: '',
    originalPrice: '',
    price: '',
    description: '',
    level: 'Intermédiaire',
    duration: '10h 00min',
    image: '/images/default-course.jpg',
    discountPercentage: 0,
    hasPromotion: false,
    status: 'draft'
  });

  // État pour les quiz
  const [quizzes, setQuizzes] = useState([]);
  const [newQuiz, setNewQuiz] = useState({
    title: '',
    description: '',
    duration: 30,
    passingScore: 60,
    questions: []
  });

  const [currentQuestion, setCurrentQuestion] = useState({
    questionText: '',
    questionType: 'multiple_choice',
    options: ['', '', '', ''],
    correctAnswer: '',
    points: 1
  });

  // Images par défaut disponibles
  const defaultImages = [
    { url: '/images/react.jpg', label: 'React' },
    { url: '/images/figma.webp', label: 'Figma' },
    { url: '/images/marketing-digital.jpg', label: 'Marketing' },
    { url: '/images/python.jpeg', label: 'Python' },
    { url: '/images/adobe.jpg', label: 'Adobe' },
    { url: '/images/agile.jpeg', label: 'Agile' },
    { url: '/images/ai.jpeg', label: 'Intelligence Artificielle' }, 
    { url: '/images/cour.png', label: 'Cours Général' },
    { url: '/images/default-course.jpg', label: 'Défaut' }
  ];

  // ========== FONCTIONS POUR LES COURS ==========
  const calculateDiscountPercentage = (originalPrice, promoPrice) => {
    const original = parseFloat(originalPrice);
    const promo = parseFloat(promoPrice);
    
    if (!original || !promo || original <= 0 || promo <= 0) {
      return 0;
    }
    
    if (promo >= original) {
      return 0;
    }
    
    const discount = ((original - promo) / original) * 100;
    return Math.round(discount);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    
    setNewCourse(prev => {
      const updatedCourse = {
        ...prev,
        [name]: value
      };
      
      if (name === 'originalPrice' || name === 'price') {
        const originalPrice = name === 'originalPrice' ? value : prev.originalPrice;
        const promoPrice = name === 'price' ? value : prev.price;
        
        if (originalPrice && promoPrice) {
          const original = parseFloat(originalPrice);
          const promo = parseFloat(promoPrice);
          
          if (promo >= original) {
            updatedCourse.discountPercentage = 0;
            updatedCourse.hasPromotion = false;
          } else {
            const discountPercentage = calculateDiscountPercentage(original, promo);
            updatedCourse.discountPercentage = discountPercentage;
            updatedCourse.hasPromotion = discountPercentage > 0;
          }
        } else {
          updatedCourse.discountPercentage = 0;
          updatedCourse.hasPromotion = false;
        }
      }
      
      return updatedCourse;
    });
  };

  const handleImageUrlChange = (e) => {
    const { value } = e.target;
    setNewCourse(prev => ({
      ...prev,
      image: value || '/images/default-course.jpg'
    }));
  };

  const handleSelectDefaultImage = (imageUrl) => {
    setNewCourse(prev => ({
      ...prev,
      image: imageUrl
    }));
  };

  const handleSubmitCourse = (e) => {
    e.preventDefault();
    
    if (!newCourse.title || !newCourse.category || !newCourse.instructor || !newCourse.originalPrice) {
      alert('❌ Veuillez remplir tous les champs obligatoires');
      return;
    }
    
    const originalPrice = parseFloat(newCourse.originalPrice);
    const promoPrice = parseFloat(newCourse.price) || originalPrice;
    
    if (promoPrice > originalPrice) {
      alert('❌ Le prix promotionnel ne peut pas être supérieur au prix original');
      return;
    }
    
    if (originalPrice <= 0) {
      alert('❌ Le prix original doit être supérieur à 0');
      return;
    }

    const courseData = {
      title: newCourse.title,
      category: newCourse.category,
      instructor: newCourse.instructor,
      price: promoPrice,
      originalPrice: newCourse.hasPromotion ? originalPrice : null,
      description: newCourse.description,
      level: newCourse.level,
      duration: newCourse.duration,
      image: newCourse.image,
      discountPercentage: newCourse.discountPercentage,
      status: newCourse.status
    };

    try {
      addCourse(courseData);
      setNewCourse({
        title: '',
        category: '',
        instructor: '',
        originalPrice: '',
        price: '',
        description: '',
        level: 'Intermédiaire',
        duration: '10h 00min',
        image: '/images/default-course.jpg',
        discountPercentage: 0,
        hasPromotion: false,
        status: 'draft'
      });
      setShowNewCourseForm(false);
      alert('✅ Cours créé avec succès !');
    } catch (error) {
      console.error('❌ Erreur lors de la création du cours:', error);
      alert('❌ Erreur lors de la création du cours');
    }
  };

  const handleDeleteCourse = (courseId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours ?')) {
      deleteCourse(courseId);
      alert('✅ Cours supprimé avec succès !');
    }
  };

  const handleCloseModal = () => {
    setShowNewCourseForm(false);
    setNewCourse({
      title: '',
      category: '',
      instructor: '',
      originalPrice: '',
      price: '',
      description: '',
      level: 'Intermédiaire',
      duration: '10h 00min',
      image: '/images/default-course.jpg',
      discountPercentage: 0,
      hasPromotion: false,
      status: 'draft'
    });
  };

  const handleNewCourseClick = () => {
    setShowNewCourseForm(true);
  };

  // ========== FONCTIONS POUR LES QUIZ ==========
  const handleAddQuiz = () => {
    setShowNewQuizForm(true);
    setEditingQuiz(null);
    setNewQuiz({
      title: '',
      description: '',
      duration: 30,
      passingScore: 60,
      questions: []
    });
  };

  const handleEditQuiz = (quiz) => {
    setShowNewQuizForm(true);
    setEditingQuiz(quiz);
    setNewQuiz(quiz);
  };

  const handleDeleteQuiz = (quizId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce quiz ?')) {
      setQuizzes(prev => prev.filter(quiz => quiz.id !== quizId));
      alert('✅ Quiz supprimé avec succès !');
    }
  };

  const handleQuizInputChange = (e) => {
    const { name, value } = e.target;
    setNewQuiz(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleAddQuestion = () => {
    if (!currentQuestion.questionText || !currentQuestion.correctAnswer) {
      alert('Veuillez remplir tous les champs de la question');
      return;
    }

    const newQuestion = {
      id: Date.now(),
      ...currentQuestion
    };

    setNewQuiz(prev => ({
      ...prev,
      questions: [...prev.questions, newQuestion]
    }));

    setCurrentQuestion({
      questionText: '',
      questionType: 'multiple_choice',
      options: ['', '', '', ''],
      correctAnswer: '',
      points: 1
    });
  };

  const handleRemoveQuestion = (questionId) => {
    setNewQuiz(prev => ({
      ...prev,
      questions: prev.questions.filter(q => q.id !== questionId)
    }));
  };

  const handleQuestionInputChange = (e) => {
    const { name, value } = e.target;
    setCurrentQuestion(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleOptionChange = (index, value) => {
    const newOptions = [...currentQuestion.options];
    newOptions[index] = value;
    setCurrentQuestion(prev => ({ ...prev, options: newOptions }));
  };

  const handleSubmitQuiz = (e) => {
    e.preventDefault();
    
    if (!newQuiz.title || !newQuiz.description || newQuiz.questions.length === 0) {
      alert('Veuillez remplir tous les champs obligatoires et ajouter au moins une question');
      return;
    }

    const quizData = {
      id: editingQuiz ? editingQuiz.id : `quiz_${Date.now()}`,
      ...newQuiz,
      createdAt: new Date().toISOString(),
      totalPoints: newQuiz.questions.reduce((total, question) => total + question.points, 0)
    };

    if (editingQuiz) {
      setQuizzes(prev => prev.map(quiz => quiz.id === editingQuiz.id ? quizData : quiz));
      alert('✅ Quiz modifié avec succès !');
    } else {
      setQuizzes(prev => [...prev, quizData]);
      alert('✅ Quiz créé avec succès !');
    }

    setShowNewQuizForm(false);
    setEditingQuiz(null);
  };

  const handleCloseQuizModal = () => {
    setShowNewQuizForm(false);
    setEditingQuiz(null);
    setNewQuiz({
      title: '',
      description: '',
      duration: 30,
      passingScore: 60,
      questions: []
    });
  };

  // Données mockées
  const stats = {
    totalRevenue: 125000,
    monthlyRevenue: 25000,
    totalStudents: 1560,
    totalCourses: courses.length,
    totalInstructors: 8,
    activeUsers: 42,
    conversionRate: 15.5,
    monthlyGrowth: 12.5
  };

  const users = [
    {
      id: 1,
      displayName: "Ahmed Ben Salah",
      email: "ahmed@example.com",
      role: "student",
      online: true,
      active: true,
      createdAt: "2024-01-15",
      lastLogin: "2024-01-20"
    },
    {
      id: 2, 
      displayName: "Sarah Trabelsi",
      email: "sarah@example.com",
      role: "instructor",
      online: false,
      active: true,
      createdAt: "2024-01-10",
      lastLogin: "2024-01-18"
    },
    {
      id: 3,
      displayName: "Mohamed Dridi",
      email: "mohamed@example.com", 
      role: "instructor",
      online: true,
      active: true,
      createdAt: "2024-01-05",
      lastLogin: "2024-01-20"
    }
  ];

  const popularCourses = [
    {
      id: 1,
      title: "React Avancé - Les Hooks et Context API",
      category: "Développement",
      instructor: "Ahmed Ben Ali",
      enrollmentCount: 1240,
      revenue: 110360
    },
    {
      id: 2,
      title: "UI/UX Design avec Figma",
      category: "Design",
      instructor: "Sarah Trabelsi",
      enrollmentCount: 890,
      revenue: 61410
    },
    {
      id: 3,
      title: "Marketing Digital 2024",
      category: "Business", 
      instructor: "Mohamed Dridi",
      enrollmentCount: 1560,
      revenue: 123240
    }
  ];

  if (!isAdmin) {
    return (
      <div className="admin-dashboard">
        <div className="access-denied">
          <h2>Welcome</h2>
          <p>Chère admin</p>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard">
      <div className="admin-layout">
        {/* Navigation Sidebar */}
        <nav className="admin-sidebar">
          <div className="sidebar-header">
            <h2>EduPlatform Admin</h2>
            <p>Tableau de Bord</p>
          </div>
          
          <div className="sidebar-nav">
            <button 
              className={`nav-item ${activeTab === 'overview' ? 'active' : ''}`}
              onClick={() => setActiveTab('overview')}
            >
              <span className="nav-icon">📊</span>
              <span className="nav-label">Vue d'ensemble</span>
            </button>
            
            <button 
              className={`nav-item ${activeTab === 'courses' ? 'active' : ''}`}
              onClick={() => setActiveTab('courses')}
            >
              <span className="nav-icon">📚</span>
              <span className="nav-label">Gestion des Cours</span>
            </button>
            
            <button 
              className={`nav-item ${activeTab === 'quizzes' ? 'active' : ''}`}
              onClick={() => setActiveTab('quizzes')}
            >
              <span className="nav-icon">🎯</span>
              <span className="nav-label">Gestion des Quiz</span>
            </button>
            
            <button 
              className={`nav-item ${activeTab === 'users' ? 'active' : ''}`}
              onClick={() => setActiveTab('users')}
            >
              <span className="nav-icon">👥</span>
              <span className="nav-label">Utilisateurs</span>
            </button>
            
            <button 
              className={`nav-item ${activeTab === 'payments' ? 'active' : ''}`}
              onClick={() => setActiveTab('payments')}
            >
              <span className="nav-icon">💳</span>
              <span className="nav-label">Paiements</span>
            </button>
          </div>
        </nav>

        {/* Contenu Principal */}
        <main className="admin-main">
          <header className="admin-header">
            <div className="header-title">
              <h1>
                {activeTab === 'overview' && 'Vue d\'Ensemble'}
                {activeTab === 'courses' && 'Gestion des Cours'}
                {activeTab === 'quizzes' && 'Gestion des Quiz'}
                {activeTab === 'users' && 'Gestion des Utilisateurs'}
                {activeTab === 'payments' && 'Gestion des Paiements'}
              </h1>
              <p>Bienvenue, {user && user.displayName ? user.displayName : 'Administrateur'} 👋</p>
            </div>
          </header>

          <div className="admin-content">
            {/* Vue d'ensemble */}
            {activeTab === 'overview' && (
              <div className="overview-tab">
                <div className="stats-grid">
                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon revenue">💰</div>
                      <div className="stat-trend positive">+{stats.monthlyGrowth}%</div>
                    </div>
                    <div className="stat-value">{stats.totalRevenue.toLocaleString()} TND</div>
                    <div className="stat-label">Revenus Totaux</div>
                    <div className="stat-subtitle">{stats.monthlyRevenue.toLocaleString()} TND ce mois</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon students">👥</div>
                      <div className="stat-trend positive">+12%</div>
                    </div>
                    <div className="stat-value">{stats.totalStudents}</div>
                    <div className="stat-label">Étudiants Actifs</div>
                    <div className="stat-subtitle">{stats.activeUsers} en ligne</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon courses">📚</div>
                      <div className="stat-trend positive">+5%</div>
                    </div>
                    <div className="stat-value">{stats.totalCourses}</div>
                    <div className="stat-label">Cours Disponibles</div>
                    <div className="stat-subtitle">{stats.totalInstructors} formateurs</div>
                  </div>

                  <div className="stat-card">
                    <div className="stat-header">
                      <div className="stat-icon conversion">📈</div>
                      <div className="stat-trend positive">+8%</div>
                    </div>
                    <div className="stat-value">{stats.conversionRate}%</div>
                    <div className="stat-label">Taux de Conversion</div>
                    <div className="stat-subtitle">Performance moyenne</div>
                  </div>
                </div>

                {/* Graphiques Simplifiés */}
                <div className="charts-grid">
                  <div className="chart-card">
                    <h3>Revenus Mensuels</h3>
                    <div className="simple-chart">
                      <div className="chart-bars">
                        {[
                          { month: 'Jan', revenue: 12000 },
                          { month: 'Fév', revenue: 19000 },
                          { month: 'Mar', revenue: 15000 },
                          { month: 'Avr', revenue: 22000 },
                          { month: 'Mai', revenue: 18000 },
                          { month: 'Jun', revenue: 25000 }
                        ].map((item, index) => (
                          <div key={index} className="chart-bar-container">
                            <div 
                              className="chart-bar" 
                              style={{ height: `${(item.revenue / 30000) * 100}%` }}
                            ></div>
                            <span className="chart-label">{item.month}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>

                  <div className="chart-card">
                    <h3>Répartition par Catégorie</h3>
                    <div className="simple-pie">
                      <div className="pie-chart">
                        <div className="pie-segment development"></div>
                        <div className="pie-segment design"></div>
                        <div className="pie-segment business"></div>
                        <div className="pie-segment marketing"></div>
                      </div>
                      <div className="pie-legend">
                        <div className="legend-item">
                          <span className="legend-color development"></span>
                          <span>Développement (40%)</span>
                        </div>
                        <div className="legend-item">
                          <span className="legend-color design"></span>
                          <span>Design (25%)</span>
                        </div>
                        <div className="legend-item">
                          <span className="legend-color business"></span>
                          <span>Business (20%)</span>
                        </div>
                        <div className="legend-item">
                          <span className="legend-color marketing"></span>
                          <span>Marketing (15%)</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Cours Populaires */}
                <div className="popular-courses">
                  <h3>Cours les Plus Populaires</h3>
                  <div className="courses-list">
                    {popularCourses.map((course, index) => (
                      <div key={course.id} className="popular-course-item">
                        <span className="rank">#{index + 1}</span>
                        <div className="course-image-placeholder"></div>
                        <div className="course-info">
                          <h4>{course.title}</h4>
                          <p>{course.category} • {course.instructor}</p>
                        </div>
                        <div className="course-stats">
                          <span className="students">👥 {course.enrollmentCount}</span>
                          <span className="revenue">💰 {course.revenue.toLocaleString()} TND</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Gestion des Cours */}
            {activeTab === 'courses' && (
              <div className="courses-tab">
                <div className="tab-header">
                  <h2>Gestion des Cours ({courses.length} cours)</h2>
                  <div style={{ display: 'flex', gap: '15px' }}>
                    <button 
                      className="btn btn-primary"
                      onClick={handleNewCourseClick}
                    >
                      + Nouveau Cours
                    </button>
                  </div>
                </div>

                {/* MODAL DE CRÉATION DE COURS */}
                {showNewCourseForm && (
                  <div className="modal-overlay">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h3>Créer un Nouveau Cours</h3>
                        <button 
                          className="btn-icon"
                          onClick={handleCloseModal}
                        >
                          ✕
                        </button>
                      </div>
                      <form onSubmit={handleSubmitCourse}>
                        <div className="form-group">
                          <label>Titre du cours *</label>
                          <input
                            type="text"
                            name="title"
                            value={newCourse.title}
                            onChange={handleInputChange}
                            required
                            placeholder="Ex: React Avancé - Les Hooks"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Catégorie *</label>
                          <select
                            name="category"
                            value={newCourse.category}
                            onChange={handleInputChange}
                            required
                          >
                            <option value="">Sélectionnez une catégorie</option>
                            <option value="Développement">Développement</option>
                            <option value="Design">Design</option>
                            <option value="Business">Business</option>
                            <option value="Marketing">Marketing</option>
                          </select>
                        </div>
                        
                        <div className="form-group">
                          <label>Formateur *</label>
                          <input
                            type="text"
                            name="instructor"
                            value={newCourse.instructor}
                            onChange={handleInputChange}
                            required
                            placeholder="Ex: Ahmed Ben Ali"
                          />
                        </div>

                        <div className="form-group">
                          <label>Image du cours</label>
                          <input
                            type="url"
                            name="image"
                            value={newCourse.image}
                            onChange={handleImageUrlChange}
                            placeholder="https://exemple.com/image.jpg"
                            style={{marginBottom: '15px'}}
                          />
                          
                          <div style={{marginBottom: '15px'}}>
                            <small style={{color: '#666', display: 'block', marginBottom: '8px'}}>
                              Ou choisir une image prédéfinie :
                            </small>
                            <div style={{
                              display: 'grid',
                              gridTemplateColumns: 'repeat(4, 1fr)',
                              gap: '8px'
                            }}>
                              {defaultImages.map((img, index) => (
                                <div
                                  key={index}
                                  onClick={() => handleSelectDefaultImage(img.url)}
                                  style={{
                                    border: newCourse.image === img.url ? '3px solid var(--primary-color)' : '2px solid #ddd',
                                    borderRadius: '6px',
                                    overflow: 'hidden',
                                    cursor: 'pointer',
                                    background: '#f8f9fa',
                                    transition: 'all 0.3s ease'
                                  }}
                                >
                                  <div 
                                    style={{
                                      width: '100%',
                                      height: '60px',
                                      backgroundImage: `url(${img.url})`,
                                      backgroundSize: 'cover',
                                      backgroundPosition: 'center'
                                    }}
                                    onError={(e) => {
                                      console.log('❌ Image non trouvée:', img.url);
                                      e.target.style.background = '#ffcccc';
                                    }}
                                  ></div>
                                  <div style={{
                                    padding: '4px',
                                    textAlign: 'center',
                                    fontSize: '0.7em',
                                    background: newCourse.image === img.url ? 'var(--primary-color)' : 'transparent',
                                    color: newCourse.image === img.url ? 'white' : '#666'
                                  }}>
                                    {img.label}
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>

                          {newCourse.image && (
                            <div style={{
                              marginTop: '10px',
                              textAlign: 'center',
                              padding: '10px',
                              background: '#f8f9fa',
                              borderRadius: '6px',
                              border: '1px solid #e9ecef'
                            }}>
                              <strong>Aperçu :</strong>
                              <div style={{
                                width: '120px',
                                height: '80px',
                                margin: '10px auto',
                                border: '1px solid #ddd',
                                borderRadius: '4px',
                                overflow: 'hidden'
                              }}>
                                <img 
                                  src={newCourse.image} 
                                  alt="Aperçu" 
                                  style={{
                                    width: '100%',
                                    height: '100%',
                                    objectFit: 'cover'
                                  }}
                                  onError={(e) => {
                                    console.log('❌ Erreur de chargement de l\'image:', newCourse.image);
                                    e.target.src = '/images/default-course.jpg';
                                  }}
                                />
                              </div>
                            </div>
                          )}
                          
                          <small style={{color: '#666', fontSize: '0.8em'}}>
                            Entrez une URL d'image ou choisissez une option rapide
                          </small>
                        </div>

                        <div className="form-group">
                          <label>Prix Original (TND) *</label>
                          <input
                            type="number"
                            name="originalPrice"
                            value={newCourse.originalPrice}
                            onChange={handleInputChange}
                            required
                            placeholder="Ex: 129"
                            min="1"
                            step="0.01"
                          />
                        </div>

                        <div className="form-group">
                          <label>Prix Promotionnel (TND)</label>
                          <input
                            type="number"
                            name="price"
                            value={newCourse.price}
                            onChange={handleInputChange}
                            placeholder="Ex: 89 (laisser vide pour pas de promotion)"
                            min="1"
                            step="0.01"
                          />
                          <small style={{color: '#666', fontSize: '0.8em'}}>
                            Laisser vide si pas de promotion
                          </small>
                        </div>

                        <div className="form-group">
                          <label>Pourcentage de Promotion</label>
                          <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '10px',
                            padding: '10px',
                            background: newCourse.hasPromotion ? '#f0f9ff' : '#f8f9fa',
                            border: `1px solid ${newCourse.hasPromotion ? '#bae6fd' : '#e9ecef'}`,
                            borderRadius: '6px'
                          }}>
                            <input
                              type="number"
                              name="discountPercentage"
                              value={newCourse.discountPercentage}
                              readOnly
                              style={{
                                flex: 1,
                                background: 'transparent',
                                border: 'none',
                                fontWeight: 'bold',
                                color: newCourse.hasPromotion ? '#22c55e' : '#666'
                              }}
                            />
                            <span style={{
                              color: newCourse.hasPromotion ? '#22c55e' : '#666',
                              fontWeight: 'bold'
                            }}>%</span>
                          </div>
                          
                          {newCourse.hasPromotion && (
                            <div style={{
                              marginTop: '10px',
                              padding: '12px',
                              background: '#ecfdf5',
                              border: '1px solid #d1fae5',
                              borderRadius: '6px'
                            }}>
                              <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                                <div>
                                  <div style={{fontSize: '0.9em', color: '#666'}}>Prix original</div>
                                  <del style={{color: '#999', fontSize: '1.1em'}}>{newCourse.originalPrice} TND</del>
                                </div>
                                <div style={{fontSize: '1.5em', color: '#dc2626'}}>→</div>
                                <div>
                                  <div style={{fontSize: '0.9em', color: '#666'}}>Prix promotionnel</div>
                                  <strong style={{color: '#e91e63', fontSize: '1.3em'}}>{newCourse.price} TND</strong>
                                </div>
                              </div>
                              <div style={{
                                marginTop: '8px',
                                textAlign: 'center',
                                background: '#22c55e',
                                color: 'white',
                                padding: '4px 8px',
                                borderRadius: '12px',
                                fontSize: '0.9em',
                                fontWeight: 'bold'
                              }}>
                                Économie de {newCourse.discountPercentage}%
                              </div>
                            </div>
                          )}
                          
                          {parseFloat(newCourse.price) > parseFloat(newCourse.originalPrice) && newCourse.originalPrice && (
                            <div style={{
                              marginTop: '10px',
                              padding: '8px',
                              background: '#fef2f2',
                              border: '1px solid #fecaca',
                              borderRadius: '4px',
                              color: '#dc2626',
                              fontSize: '0.8em'
                            }}>
                              ⚠️ Le prix promotionnel ne peut pas être supérieur au prix original
                            </div>
                          )}
                        </div>
                        
                        <div className="form-group">
                          <label>Niveau</label>
                          <select
                            name="level"
                            value={newCourse.level}
                            onChange={handleInputChange}
                          >
                            <option value="Débutant">Débutant</option>
                            <option value="Intermédiaire">Intermédiaire</option>
                            <option value="Avancé">Avancé</option>
                            <option value="Tous niveaux">Tous niveaux</option>
                          </select>
                        </div>
                        
                        <div className="form-group">
                          <label>Durée</label>
                          <input
                            type="text"
                            name="duration"
                            value={newCourse.duration}
                            onChange={handleInputChange}
                            placeholder="Ex: 10h 30min"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Description</label>
                          <textarea
                            name="description"
                            value={newCourse.description}
                            onChange={handleInputChange}
                            placeholder="Description du cours..."
                            rows="4"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Statut</label>
                          <select
                            name="status"
                            value={newCourse.status}
                            onChange={handleInputChange}
                          >
                            <option value="draft">Brouillon</option>
                            <option value="published">Publié</option>
                          </select>
                        </div>
                        
                        <div className="modal-actions">
                          <button 
                            type="button" 
                            className="btn btn-secondary"
                            onClick={handleCloseModal}
                          >
                            Annuler
                          </button>
                          <button 
                            type="submit" 
                            className="btn btn-primary"
                          >
                            Créer le Cours
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}

                {/* TABLEAU DES COURS */}
                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Titre</th>
                        <th>Catégorie</th>
                        <th>Formateur</th>
                        <th>Prix</th>
                        <th>Promotion</th>
                        <th>Étudiants</th>
                        <th>Statut</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {courses.map(course => (
                        <tr key={course.id}>
                          <td>
                            <div className="course-cell">
                              <div 
                                className="course-thumb-placeholder"
                                style={{
                                  backgroundImage: `url(${course.image})`,
                                  backgroundSize: 'cover',
                                  backgroundPosition: 'center'
                                }}
                              >
                                {!course.image || course.image === '/images/default-course.jpg' ? (
                                  <span>📚</span>
                                ) : null}
                              </div>
                              <div style={{minWidth: 0, flex: 1}}>
                                <strong style={{display: 'block', marginBottom: '8px'}}>{course.title}</strong>
                                <CourseDescription description={course.description} />
                              </div>
                            </div>
                          </td>
                          <td>{course.category}</td>
                          <td>{course.instructor}</td>
                          <td>
                            <div>
                              {course.hasPromotion ? (
                                <>
                                  <del style={{color: '#999', fontSize: '0.9em'}}>
                                    {course.originalPrice} TND
                                  </del>
                                  <br />
                                  <strong style={{color: '#e91e63'}}>
                                    {course.price} TND
                                  </strong>
                                </>
                              ) : (
                                <strong>{course.price} TND</strong>
                              )}
                            </div>
                          </td>
                          <td>
                            {course.hasPromotion ? (
                              <span style={{
                                background: '#22c55e',
                                color: 'white',
                                padding: '4px 8px',
                                borderRadius: '12px',
                                fontSize: '0.8em',
                                fontWeight: 'bold'
                              }}>
                                -{course.discountPercentage}%
                              </span>
                            ) : (
                              <span style={{color: '#999'}}>Aucune</span>
                            )}
                          </td>
                          <td>{course.students || 0}</td>
                          <td>
                            <span className={`status-badge ${course.status}`}>
                              {course.status === 'published' ? 'Publié' : 'Brouillon'}
                            </span>
                          </td>
                          <td>
                            <div className="action-buttons">
                              <button className="btn-icon" title="Éditer">✏️</button>
                              <button 
                                className="btn-icon btn-danger" 
                                title="Supprimer"
                                onClick={() => handleDeleteCourse(course.id)}
                              >
                                🗑️
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Gestion des Quiz */}
            {activeTab === 'quizzes' && (
              <div className="quizzes-tab">
                <div className="tab-header">
                  <h2>Gestion des Quiz ({quizzes.length} quiz)</h2>
                  <button 
                    className="btn btn-primary"
                    onClick={handleAddQuiz}
                  >
                    🎯 Créer un Quiz
                  </button>
                </div>

                {/* MODAL DE CRÉATION/MODIFICATION DE QUIZ */}
                {showNewQuizForm && (
                  <div className="modal-overlay">
                    <div className="modal-content" style={{ maxWidth: '800px', maxHeight: '90vh', overflowY: 'auto' }}>
                      <div className="modal-header">
                        <h3>{editingQuiz ? 'Modifier le Quiz' : 'Créer un Nouveau Quiz'}</h3>
                        <button 
                          className="btn-icon"
                          onClick={handleCloseQuizModal}
                        >
                          ✕
                        </button>
                      </div>
                      <form onSubmit={handleSubmitQuiz}>
                        <div className="form-group">
                          <label>Titre du quiz *</label>
                          <input
                            type="text"
                            name="title"
                            value={newQuiz.title}
                            onChange={handleQuizInputChange}
                            required
                            placeholder="Ex: Quiz React Avancé"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Description *</label>
                          <textarea
                            name="description"
                            value={newQuiz.description}
                            onChange={handleQuizInputChange}
                            required
                            placeholder="Description du quiz..."
                            rows="3"
                          />
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Durée (minutes) *</label>
                            <input
                              type="number"
                              name="duration"
                              value={newQuiz.duration}
                              onChange={handleQuizInputChange}
                              required
                              min="5"
                            />
                          </div>

                          <div className="form-group">
                            <label>Score de passage (%) *</label>
                            <input
                              type="number"
                              name="passingScore"
                              value={newQuiz.passingScore}
                              onChange={handleQuizInputChange}
                              required
                              min="0"
                              max="100"
                            />
                          </div>
                        </div>

                        {/* FORMULAIRE D'AJOUT DE QUESTION */}
                        <div className="form-section">
                          <h4>Ajouter une question</h4>
                          
                          <div className="form-group">
                            <label>Type de question</label>
                            <select
                              name="questionType"
                              value={currentQuestion.questionType}
                              onChange={handleQuestionInputChange}
                            >
                              <option value="multiple_choice">Choix multiple</option>
                              <option value="true_false">Vrai/Faux</option>
                              <option value="text">Réponse texte</option>
                            </select>
                          </div>

                          <div className="form-group">
                            <label>Question *</label>
                            <textarea
                              name="questionText"
                              value={currentQuestion.questionText}
                              onChange={handleQuestionInputChange}
                              placeholder="Entrez votre question"
                              required
                              rows="3"
                            />
                          </div>

                          {currentQuestion.questionType === 'multiple_choice' && (
                            <div className="options-form">
                              <label>Options *</label>
                              {currentQuestion.options.map((option, index) => (
                                <div key={index} className="option-input">
                                  <input
                                    type="text"
                                    value={option}
                                    onChange={(e) => handleOptionChange(index, e.target.value)}
                                    placeholder={`Option ${index + 1}`}
                                    required
                                  />
                                  <label className="radio-label">
                                    <input
                                      type="radio"
                                      name="correctAnswer"
                                      checked={currentQuestion.correctAnswer === option}
                                      onChange={() => setCurrentQuestion(prev => ({ ...prev, correctAnswer: option }))}
                                      required
                                    />
                                    Correct
                                  </label>
                                </div>
                              ))}
                            </div>
                          )}

                          {currentQuestion.questionType === 'true_false' && (
                            <div className="form-group">
                              <label>Réponse correcte *</label>
                              <select
                                value={currentQuestion.correctAnswer}
                                onChange={(e) => setCurrentQuestion(prev => ({ ...prev, correctAnswer: e.target.value }))}
                                required
                              >
                                <option value="">Sélectionnez</option>
                                <option value="true">Vrai</option>
                                <option value="false">Faux</option>
                              </select>
                            </div>
                          )}

                          {currentQuestion.questionType === 'text' && (
                            <div className="form-group">
                              <label>Réponse correcte *</label>
                              <input
                                type="text"
                                value={currentQuestion.correctAnswer}
                                onChange={(e) => setCurrentQuestion(prev => ({ ...prev, correctAnswer: e.target.value }))}
                                placeholder="Réponse attendue"
                                required
                              />
                            </div>
                          )}

                          <div className="form-group">
                            <label>Points</label>
                            <input
                              type="number"
                              name="points"
                              value={currentQuestion.points}
                              onChange={handleQuestionInputChange}
                              min="1"
                            />
                          </div>

                          <button type="button" onClick={handleAddQuestion} className="btn btn-secondary">
                            + Ajouter cette question
                          </button>
                        </div>

                        {/* LISTE DES QUESTIONS AJOUTÉES */}
                        {newQuiz.questions.length > 0 && (
                          <div className="form-section">
                            <h4>Questions ajoutées ({newQuiz.questions.length})</h4>
                            <div className="questions-list">
                              {newQuiz.questions.map((question, index) => (
                                <div key={question.id} className="question-item">
                                  <div className="question-header">
                                    <span className="question-number">Question {index + 1}</span>
                                    <button 
                                      type="button" 
                                      onClick={() => handleRemoveQuestion(question.id)}
                                      className="btn btn-danger btn-sm"
                                    >
                                      Supprimer
                                    </button>
                                  </div>
                                  <p className="question-text">{question.questionText}</p>
                                  <div className="question-meta">
                                    <span>Type: {question.questionType}</span>
                                    <span>Points: {question.points}</span>
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        <div className="modal-actions">
                          <button 
                            type="button" 
                            className="btn btn-secondary"
                            onClick={handleCloseQuizModal}
                          >
                            Annuler
                          </button>
                          <button 
                            type="submit" 
                            className="btn btn-primary"
                            disabled={newQuiz.questions.length === 0}
                          >
                            {editingQuiz ? 'Modifier le Quiz' : 'Créer le Quiz'}
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}

                {/* TABLEAU DES QUIZ */}
                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Titre</th>
                        <th>Description</th>
                        <th>Durée</th>
                        <th>Score de Passage</th>
                        <th>Questions</th>
                        <th>Points Total</th>
                        <th>Créé le</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {quizzes.length === 0 ? (
                        <tr>
                          <td colSpan="8" style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
                            <div style={{ fontSize: '3em', marginBottom: '15px' }}>🎯</div>
                            <h3>Aucun quiz créé pour le moment</h3>
                            <p style={{ marginBottom: '20px' }}>Commencez par créer votre premier quiz</p>
                            <button 
                              onClick={handleAddQuiz}
                              className="btn btn-primary"
                            >
                              🎯 Créer votre premier quiz
                            </button>
                          </td>
                        </tr>
                      ) : (
                        quizzes.map(quiz => (
                          <tr key={quiz.id}>
                            <td>
                              <strong>{quiz.title}</strong>
                            </td>
                            <td>
                              <CourseDescription description={quiz.description} />
                            </td>
                            <td>{quiz.duration} min</td>
                            <td>{quiz.passingScore}%</td>
                            <td>{quiz.questions.length}</td>
                            <td>{quiz.totalPoints} pts</td>
                            <td>{new Date(quiz.createdAt).toLocaleDateString('fr-FR')}</td>
                            <td>
                              <div className="action-buttons">
                                <button 
                                  className="btn-icon" 
                                  title="Éditer"
                                  onClick={() => handleEditQuiz(quiz)}
                                >
                                  ✏️
                                </button>
                                <button 
                                  className="btn-icon btn-danger" 
                                  title="Supprimer"
                                  onClick={() => handleDeleteQuiz(quiz.id)}
                                >
                                  🗑️
                                </button>
                                <Link 
                                  to={`/quiz/${quiz.id}`}
                                  className="btn-icon"
                                  title="Prévisualiser"
                                  style={{ textDecoration: 'none' }}
                                >
                                  👁️
                                </Link>
                              </div>
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Gestion des Utilisateurs */}
            {activeTab === 'users' && (
              <div className="users-tab">
                <div className="tab-header">
                  <h2>Gestion des Utilisateurs</h2>
                </div>

                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Utilisateur</th>
                        <th>Email</th>
                        <th>Rôle</th>
                        <th>Inscription</th>
                        <th>Statut</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map(user => (
                        <tr key={user.id}>
                          <td>
                            <div className="user-cell">
                              <div className="user-avatar">
                                <div className="avatar-placeholder">
                                  {user.displayName.charAt(0)}
                                </div>
                              </div>
                              <div>
                                <strong>{user.displayName}</strong>
                                <p className="user-meta">
                                  Dernière connexion: {user.lastLogin}
                                </p>
                              </div>
                            </div>
                          </td>
                          <td>{user.email}</td>
                          <td>
                            <span className={`badge badge-${user.role}`}>
                              {user.role === 'instructor' ? 'Formateur' : 'Étudiant'}
                            </span>
                          </td>
                          <td>{user.createdAt}</td>
                          <td>
                            <div className="status-cell">
                              <span className={`badge ${user.online ? 'badge-success' : 'badge-warning'}`}>
                                {user.online ? 'En ligne' : 'Hors ligne'}
                              </span>
                              <span className={`badge ${user.active ? 'badge-success' : 'badge-danger'}`}>
                                {user.active ? 'Actif' : 'Inactif'}
                              </span>
                            </div>
                          </td>
                          <td>
                            <div className="action-buttons">
                              <button className="btn-icon" title="Voir profil">👁️</button>
                              <button className="btn-icon btn-warning" title="Modifier">⚙️</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Paiements */}
            {activeTab === 'payments' && (
              <div className="payments-tab">
                <h2>Gestion des Paiements</h2>
                <div className="coming-soon">
                  <p>🚧 Intégration Paymee en cours de développement</p>
                  <div className="features-list">
                    <h4>Fonctionnalités à venir :</h4>
                    <ul>
                      <li>Historique des transactions</li>
                      <li>Statuts des paiements</li>
                      <li>Rapports financiers</li>
                      <li>Export des données</li>
                    </ul>
                  </div>
                </div>
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;
